461: struct Files<'a> {
462:     file_names: &'a [&'a str],
463: }
464: 
465: impl<'a> Files<'a> {
466:     fn new(file_names: &'a [&'a str]) -> Self {
467:         for file_name in file_names {
468:             let content = if file_name.ends_with("iliad.txt") {
469:                 ILIAD_CONTENT
470:             } else if file_name.ends_with("midsummer-night.txt") {
471:                 MIDSUMMER_NIGHT_CONTENT
472:             } else if file_name.ends_with("paradise-lost.txt") {
473:                 PARADISE_LOST_CONTENT
474:             } else {
475:                 IN_THE_WHITE_NIGHT_CONTENT
476:             };
477:             std::fs::write(file_name, content).unwrap_or_else(|_| {
478:                 panic!("Error setting up file '{file_name}' with the following content:\n{content}")
479:             });
480:         }
481: 
482:         Self { file_names }
483:     }
484: }
485: 
486: impl Drop for Files<'_> {
487:     fn drop(&mut self) {
488:         for file_name in self.file_names {
489:             std::fs::remove_file(file_name)
490:                 .unwrap_or_else(|e| panic!("Could not delete file '{file_name}': {e}"));
491:         }
492:     }
493: }
